{
 "summary": "Both target theorems state a Clay/Fefferman-style breakdown alternative for each viscosity ν > 0. (C) says there exist smooth, divergence-free, rapidly decaying initial data u₀ on ℝ³ and a smooth, rapidly decaying force f such that no pair (v, p) exists that is a C^∞ solution of Navier–Stokes on ℝ³×[0,∞), is L² at every time, and has uniformly bounded energy. (D) is the same on ℝ³/ℤ³, with periodic data and force decaying in time, ruling out periodic smooth global solutions. The definitions are faithful and the regularity hypotheses neutralize the derivative and integral junk values. The main caveat is that the periodic solution notion also requires the pressure to be 1-periodic (the Clay errata version), which slightly weakens (D) relative to the original wording.",
 "glossary": [
  {"decl": "divergence", "line": 81, "plain": "∇·v(x) = trace of Dv(x); equals 0 if v is not differentiable at x", "standard_concept": "divergence", "matches_standard": "yes", "note": "Only ever applied to smooth fields, so the junk value is never used."},
  {"decl": "IsOnePeriodic", "line": 121, "plain": "f(x + e_i) = f(x) for all x and all coordinates i", "standard_concept": "ℤⁿ-periodicity (function on the torus)", "matches_standard": "yes", "note": ""},
  {"decl": "InitialVelocityCondition", "line": 134, "plain": "u₀ is C^∞ and ∇·u₀ = 0 everywhere", "standard_concept": "Fefferman (2) plus smoothness of u°", "matches_standard": "yes", "note": ""},
  {"decl": "InitialVelocityConditionDecay", "line": 150, "plain": "In addition, for all m and K there is C with ‖D^m u₀(x)‖ ≤ C(1+|x|)^{-K}", "standard_concept": "Fefferman condition (4)", "matches_standard": "yes", "note": "The base 1+‖x‖ is positive, so there is no junk division."},
  {"decl": "InitialVelocityConditionPeriodic", "line": 164, "plain": "Smooth, divergence-free, 1-periodic u₀", "standard_concept": "Fefferman (8) for u°", "matches_standard": "yes", "note": ""},
  {"decl": "ForceCondition", "line": 175, "plain": "f (as a function of (x,t)) is C^∞ on ℝⁿ×[0,∞)", "standard_concept": "smooth force", "matches_standard": "yes", "note": ""},
  {"decl": "ForceConditionDecay", "line": 185, "plain": "In addition, all (x,t)-derivatives within ℝⁿ×[0,∞) are bounded by C(1+|x|+t)^{-K}", "standard_concept": "Fefferman condition (5)", "matches_standard": "yes", "note": ""},
  {"decl": "ForceConditionPeriodic", "line": 200, "plain": "Smooth, 1-periodic in x for t ≥ 0, with all derivatives bounded by C(1+t)^{-K}", "standard_concept": "Fefferman (8) and (9) for f", "matches_standard": "yes", "note": ""},
  {"decl": "NavierStokesExistenceAndSmoothness", "line": 217, "plain": "For all x and t ≥ 0: ∂_t v + (Dv)v = νΔv − ∇p + f, with ∂_t one-sided at t = 0; ∇·v = 0; v(·,0) = u₀; v and p are C^∞ on ℝⁿ×[0,∞)", "standard_concept": "smooth solution, Fefferman (1)-(3) and (6)/(11)", "matches_standard": "yes", "note": "Smoothness makes every fderiv, Δ and gradient genuine."},
  {"decl": "NavierStokesExistenceAndSmoothnessRn", "line": 245, "plain": "Smooth solution with v(·,t) ∈ L² for every t ≥ 0 and sup_{t≥0} ∫|v|² dx < ∞", "standard_concept": "Fefferman (6) and (7)", "matches_standard": "yes", "note": "The extra MemLp field follows from bounded energy plus continuity, so it is not a real extra restriction. It also guards the integral junk value."},
  {"decl": "NavierStokesExistenceAndSmoothnessPeriodic", "line": 262, "plain": "Smooth solution with v(·,t) and p(·,t) both 1-periodic for t ≥ 0", "standard_concept": "Fefferman (10)/(11) as amended by the Clay errata", "matches_standard": "partly", "note": "Periodic pressure is required (errata version); Fefferman's original (10) concerns u only."}
 ],
 "lean_claims": [
  {"theorem": "navier_stokes_breakdown_R3", "line": 273, "plain": "For all ν > 0 there exist u₀ : ℝ³→ℝ³ (C^∞, divergence-free, all derivatives decaying faster than any polynomial) and f : ℝ³×ℝ→ℝ³ (C^∞ on ℝ³×[0,∞), all derivatives ≤ C_{m,K}(1+|x|+t)^{-K}) such that no (v,p) exists that is C^∞ on ℝ³×[0,∞), solves NS with ∇·v = 0 and v(·,0) = u₀, has v(·,t) ∈ L² for all t ≥ 0, and has sup_t ∫|v|² < ∞."},
  {"theorem": "navier_stokes_breakdown_periodic", "line": 280, "plain": "For all ν > 0 there exist u₀ (C^∞, divergence-free, 1-periodic) and f (C^∞ on ℝ³×[0,∞), 1-periodic in x, all derivatives ≤ C(1+t)^{-K}) such that no (v,p) exists that is C^∞ on ℝ³×[0,∞), solves NS with ∇·v = 0 and v(·,0) = u₀, and has v and p 1-periodic in x for all t ≥ 0."}
 ],
 "paper_claims": [
  {"ref": "Theorem 1.1", "plain": "For every ν > 0 there exist f ∈ C_c^∞(ℝ³×(0,∞)), compact K, and smooth u, p on ℝ³×[0,1) solving NS with u(·,0) = 0, supported in K, with bounded L² norm and lim sup_{t↑1} ‖u(t)‖_∞ = ∞. Consequently no smooth global solution with bounded energy exists for this data; this is alternative (C)."},
  {"ref": "Corollary 10.6", "plain": "For every ν > 0 there is a smooth force on T³×[0,∞), compactly supported in time, such that the periodic solution with zero initial data blows up in L^∞ as t ↑ 1, and there is no global smooth periodic solution; this is alternative (D)."}
 ],
 "coverage": [
  {"paper_ref": "Theorem 1.1", "lean_theorem": "navier_stokes_breakdown_R3", "relation": "lean_weaker", "why": "Lean states only the 'consequently' part, alternative (C), with existentially chosen data. It omits u₀ = 0, compact support, the local solution and the L^∞ blowup. For alternative (C) itself the statements are equivalent."},
  {"paper_ref": "Corollary 10.6", "lean_theorem": "navier_stokes_breakdown_periodic", "relation": "lean_weaker", "why": "Lean states only the nonexistence of a global smooth periodic solution, alternative (D) in its errata form with periodic pressure. The local solution and blowup details are omitted."}
 ],
 "flags": [
  {"id": "F1", "category": "definition-mismatch", "severity": "low", "decl": "NavierStokesExistenceAndSmoothnessPeriodic", "line": 269, "paper_ref": "Corollary 10.6", "explanation": "The solution notion additionally requires the pressure to be 1-periodic. Inside ¬∃ this extra requirement makes the nonexistence claim weaker than Fefferman's original (D), where only u is required to be periodic. It matches the Clay errata, and the paper's Corollary speaks of 'the periodic solution (U, P_per)', so this is consistent with the intended version.", "polarity": "lean weaker", "probe_idea": "Restate navier_stokes_breakdown_periodic with isOnePeriodic_pressure removed, i.e. using a structure without that field, and check that the submitted proof still adapts."},
  {"id": "F2", "category": "coverage", "severity": "low", "decl": "navier_stokes_breakdown_R3", "line": 273, "paper_ref": "Theorem 1.1", "explanation": "Only the alternative (C) consequence is formalized. The paper's quantitative content (u₀ = 0, compactly supported f, L^∞ blowup at t = 1) is not stated in Lean.", "polarity": "lean weaker", "probe_idea": null}
 ],
