  {"line": 191, "rule": "junk-div", "verdict": "harmless", "why": "1 + ‖x‖ + t ≥ 1 for t ≥ 0."},
  {"line": 205, "rule": "junk-div", "verdict": "harmless", "why": "1 + t ≥ 1 for t ≥ 0."},
  {"line": 224, "rule": "nat-sub", "verdict": "harmless", "why": "This is subtraction in EuclideanSpace ℝ (Fin n), not ℕ."},
  {"line": 223, "rule": "junk-deriv", "verdict": "harmless", "why": "velocity_smooth gives differentiability on ℝⁿ×[0,∞), and Ici 0 has unique derivatives at every point, so derivWithin and fderiv are genuine."},
